# Fix the uniform region finder
def find_uniform_regions(grid, min_size=4):
    """Find all square or rectangular regions that are uniformly one value"""
    height = len(grid)
    width = len(grid[0])
    regions = []

    for h in range(min_size, height+1):
        for w in range(min_size, width+1):
            for r in range(height-h+1):
                for c in range(width-w+1):
                    val = grid[r][c]
                    is_uniform = True
                    for dr in range(h):
                        for dc in range(w):
                            if grid[r+dr][c+dc] != val:
                                is_uniform = False
                                break
                        if not is_uniform:
                            break

                    if is_uniform:
                        size = h * w
                        # Compare with existing regions
                        if not regions or size > max(r[2] for r in regions):
                            # Check if this size is already represented by a larger or equal region
                            existing_sizes = [r[2] for r in regions]
                            if size not in existing_sizes or (h*w >= existing_sizes[-1]):
                                regions.append(((r,c,h,w), val, h*w))

    return sorted(regions, key=lambda x: x[2], reverse=True)[:15]

