def get_quadrant_properties(grid, ref_r, ref_c):
    """Divide grid and check if ref is in which quadrant"""
    height = len(grid)
    width = len(grid[0])

    # Divide into 4 quadrants
    mid_row = height // 2
    mid_col = width // 2

    def get_prop(qname):
        if qname == "TL":
            return grid[:mid_row][:mid_col]
        elif qname == "TR":
            return grid[:mid_row][mid_col:]
        elif qname == "BL":
            return grid[mid_row:][:mid_col]
        elif qname == "BR":
            return grid[mid_row:][mid_col:]

        # Return dominant non-3 value from this quadrant
        vals = []
        if qname == "TL":
            for r in range(mid_row):
                for c in range(mid_col):
                    vals.append(grid[r][c])
        elif qname == "TR":
            for r in range(mid_row):
                for c in range(mid_col, width):
                    vals.append(grid[r][c])
        elif qname == "BL":
            for r in range(mid_row, height):
                for c in range(mid_col):
                    vals.append(grid[r][c])
        elif qname == "BR":
            for r in range(mid_row, height):
                for c in range(mid_col, width):
                    vals.append(grid[r][c])

        if not vals:
            return None

        # Filter out 3s and find most common
        filtered = [v for v in vals if v != 3]
        if not filtered:
            return None
        return max(set(filtered), key=filtered.count)

    props = {qname: get_prop(qname) for qname in ["TL", "TR", "BL", "BR"]}
    return props

