def get_relative_dominant(grid, ref_r, ref_c, out_row, out_col):
    """Get dominant value in a fixed region relative to (ref_r, ref_c)"""
    # Different regions for different output cells
    regions = {
        (0,0): (-2,-2), (0,1): (0,-2), (0,2): (2,-2), (0,3): (2,0),
        (1,0): (-2,0), (1,1): (0,0), (1,2): (2,0), (1,3): (2,2),
        (2,0): (-2,2), (2,1): (0,2), (2,2): (2,2), (2,3): (2,4),
        (3,0): (-2,4), (3,1): (0,4), (3,2): (2,4), (3,3): (2,6),
    }

    dr, dc = regions.get((out_row, out_col), (0,0))
    r1, c1 = int(ref_r) + dr, int(ref_c) + dc
    r2, c2 = r1 + 2, c1 + 2

    if r1 < 0 or r2 >= 16 or c1 < 0 or c2 >= 16:
        return None

    vals = []
    for r in range(r1, r2):
        for c in range(c1, c2):
            vals.append(grid[r][c])

    if vals:
        return max(set(vals), key=vals.count)
    return None

