        elif qname == "BL":
            for r in range(mid_r, height):
                for c in range(mid_c):
                    vals.append(grid[r][c])
        elif qname == "BR":
            for r in range(mid_r, height):
                for c in range(mid_c, width):
                    vals.append(grid[r][c])

        if vals:
            filtered = [v for v in vals if v != 3]
            if not filtered:
                return None
            return max(set(filtered), key=filtered.count)
